$ErrorActionPreference = "Stop"

$root = "C:\Users\yildi\Desktop\3Dcad"
$detector = Join-Path $root "src\cad\wall_detector.py"

$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$backup = Join-Path $root ("backups\wall_continuity_collinear_conflict_" + $stamp)
New-Item -ItemType Directory -Force -Path $backup | Out-Null

if (!(Test-Path $detector)) {
    throw "wall_detector.py not found."
}

Copy-Item $detector (Join-Path $backup "wall_detector.py") -Force

$tmpPy = Join-Path $env:TEMP "wall_continuity_collinear_conflict.py"
[IO.File]::WriteAllBytes($tmpPy, [Convert]::FromBase64String(""))

& py -3.12 $tmpPy

if ($LASTEXITCODE -ne 0) {
    Copy-Item (Join-Path $backup "wall_detector.py") $detector -Force
    throw "Patch failed. Previous wall_detector.py restored."
}

$env:PYTHONPATH = Join-Path $root "src"
$env:PYTHONUTF8 = "1"
$env:PYTHONIOENCODING = "utf-8"

& py -3.12 -m py_compile $detector

if ($LASTEXITCODE -ne 0) {
    Copy-Item (Join-Path $backup "wall_detector.py") $detector -Force
    throw "Compile failed. Previous wall_detector.py restored."
}

& py -3.12 -c "from cad.wall_detector import detect_walls, WallCandidate; print('CONTINUITY COLLINEAR CONFLICT PASS')"

if ($LASTEXITCODE -ne 0) {
    Copy-Item (Join-Path $backup "wall_detector.py") $detector -Force
    throw "Import failed. Previous wall_detector.py restored."
}

Write-Host ""
Write-Host "CONTINUITY / COLLINEAR CONFLICT FIXED" -ForegroundColor Green
Write-Host "When endpoint continuity sees overlapping collinear alternatives, it now prefers the longest candidate that itself touches the selected endpoint network."
Write-Host "Short helper lines are no longer allowed to win merely because they are encountered first."
Write-Host "Existing door, window, layer and final exclusion rules were not changed."
Write-Host ("Backup: " + $backup)
